import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.BDCokyix.js";const u=JSON.parse('{"title":"ADR-0005: UI revamp v0 — single UI system, panel-stack right area, ACP-based assistant","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/adrs/0005-ui-revamp-v0.md","filePath":"architecture/adrs/0005-ui-revamp-v0.md","lastUpdated":1780254295000}'),i={name:"architecture/adrs/0005-ui-revamp-v0.md"};function n(r,e,l,c,d,p){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-0005-ui-revamp-v0-—-single-ui-system-panel-stack-right-area-acp-based-assistant" tabindex="-1">ADR-0005: UI revamp v0 — single UI system, panel-stack right area, ACP-based assistant <a class="header-anchor" href="#adr-0005-ui-revamp-v0-—-single-ui-system-panel-stack-right-area-acp-based-assistant" aria-label="Permalink to &quot;ADR-0005: UI revamp v0 — single UI system, panel-stack right area, ACP-based assistant&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Soma&#39;s renderer evolved from two merged apps (the original Soma workspace and Tapia typing companion) and carries the friction of that merger:</p><ul><li>Two coexisting UI layers — a <code>@soma/ui</code> package and ad-hoc components inside <code>desktop/soma/src/renderer/src/routes/practice/</code>.</li><li>Settings flows accumulated buttons and floating CTAs in many places; there is no single rule for save behaviour.</li><li>The chat is currently absent in the renderer; future work plans called it &quot;the chat panel&quot; — a single fixed surface — but actual user needs span history, sub-pages, attached files, agenda, exercise queues, etc.</li><li>Bot membership exists in the daemon (<code>soma-daemon</code> capability model) but has no UI; nothing distinguishes a conversational LLM assistant from a programmable p2p bot.</li><li>LLM access was planned as direct OpenAI-compatible HTTP, which would force per-provider plumbing.</li><li>There is no second-window mechanism; typing exercises live inside the main app, sharing the same chrome as workspace navigation.</li><li>Density is inconsistent: shadows everywhere, oversized padding, line-heights tuned for marketing surfaces, not for 14–16&quot; laptops doing real work.</li></ul><p>The UI revamp v0 PRD (<a href="./../prd/ui-revamp-v0">prd/ui-revamp-v0.md</a>) and the six refero reference docs that accompany it (<a href="./../prd/ui-revamp-v0-refs">overview</a>, <a href="./../prd/ui-revamp-v0-refs-space-lifecycle">space lifecycle</a>, <a href="./../prd/ui-revamp-v0-refs-assistant-bots">assistant + bots</a>, <a href="./../prd/ui-revamp-v0-refs-editor">editor</a>, <a href="./../prd/ui-revamp-v0-refs-files-density">files + density</a>, <a href="./../prd/ui-revamp-v0-refs-popup-window">popup window</a>) settled the open design questions. This ADR records the architectural decisions that bind multiple flows together. Visual specifications stay in the refs docs; this ADR holds the load-bearing rules.</p><h2 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;Decisions&quot;">​</a></h2><h3 id="_1-one-ui-system-soma-ui-on-tailwind-v4-daisyui-v5" tabindex="-1">1. One UI system: <code>@soma/ui</code> on Tailwind v4 + DaisyUI v5 <a class="header-anchor" href="#_1-one-ui-system-soma-ui-on-tailwind-v4-daisyui-v5" aria-label="Permalink to &quot;1. One UI system: `@soma/ui` on Tailwind v4 + DaisyUI v5&quot;">​</a></h3><p>All shared components live in <code>@soma/ui</code>. The <code>desktop/soma/src/renderer/src/routes/practice/components/</code> tree is dismantled — reusable pieces migrate to <code>@soma/ui</code> (the <a href="./../../../../desktop/desktop-ui/src/components/tapia/char-display.tsx"><code>CharDisplay</code></a> component is already there); the rest dies. The renderer does not vend a second UI layer.</p><h3 id="_2-layout-is-a-four-column-shell-with-a-stackable-right-area" tabindex="-1">2. Layout is a four-column shell with a stackable right area <a class="header-anchor" href="#_2-layout-is-a-four-column-shell-with-a-stackable-right-area" aria-label="Permalink to &quot;2. Layout is a four-column shell with a stackable right area&quot;">​</a></h3><ul><li>52px <strong>icon spaces rail</strong> (far left)</li><li>narrow <strong>page tree column</strong> (collapsible to icon strip in tight viewports)</li><li><strong>document column</strong> (TipTap)</li><li><strong>right area</strong> — a stack of independently controllable <strong>panels</strong> (not a single chat pane)</li></ul><p>Right-area panels share a header (title · collapse · close · drag-handle) and a body. The panel container vertically stacks panels by default and supports a user-driven horizontal split (max 2 columns). Panels are pinned to a space or to a document; switching documents reflows. Chat is one panel among siblings — history, sub-pages, attached files, agenda, exercise queue, presence, etc., all live in the same container.</p><p>Width budgets degrade as the window shrinks:</p><ol><li><strong>Comfortable (≥ ~1280px usable):</strong> all columns docked, multiple panels visible.</li><li><strong>Tight (~960–1280px):</strong> docked right area collapses to icon strip; opening a panel slides it in as a right-edge drawer with overlay.</li><li><strong>Very small (&lt; ~960px):</strong> right area enters fullscreen-takeover mode when summoned. Editor is the priority surface; panels only show on demand.</li></ol><h3 id="_3-tabbed-cards-settings-ia-auto-save-on-blur-no-global-save" tabindex="-1">3. Tabbed-cards settings IA, auto-save on blur, no global Save <a class="header-anchor" href="#_3-tabbed-cards-settings-ia-auto-save-on-blur-no-global-save" aria-label="Permalink to &quot;3. Tabbed-cards settings IA, auto-save on blur, no global Save&quot;">​</a></h3><p>Space settings is a single page with horizontal pill/underline tabs (General · Members · Assistant · Bots · Sharing · Danger). Each tab is one screen of sectioned cards.</p><ul><li><strong>Save model.</strong> Auto-save on blur. Per-section Save buttons are banned. Errors surface inline under the field. Success is silent.</li><li><strong>Primary actions</strong> exist only for <em>initiation</em> (Add backend, Add bot) and <em>destruction</em> (Danger tab).</li><li><strong>Danger zone.</strong> Red-labelled card. Destructive actions open an inline slug-confirm form; the action stays disabled until the typed slug matches.</li></ul><p>This rule is universal — settings UIs across the app obey it, not just space settings.</p><h3 id="_4-llm-vs-bot-are-distinct-first-class-concepts" tabindex="-1">4. LLM vs. bot are distinct first-class concepts <a class="header-anchor" href="#_4-llm-vs-bot-are-distinct-first-class-concepts" aria-label="Permalink to &quot;4. LLM vs. bot are distinct first-class concepts&quot;">​</a></h3><ul><li><strong>LLM (assistant).</strong> Conversational space member, configured via Settings → Assistant. Soma speaks the <strong>Agent Client Protocol (ACP)</strong> — the same protocol Zed uses — so backends are pluggable: Ollama, LM Studio, Codex, OpenAI-compatible (via ACP shim). ACP backends are managed by the embedded <code>soma-agentd</code> runtime; the renderer reaches them through the napi <code>SomaHandle</code>, not by dialing services directly.</li><li><strong>Bot.</strong> Programmable p2p peer with capabilities. Added by <strong>pasting a peer address</strong> (no catalog, no discovery). RBAC governs who may add a bot and with what scope.</li></ul><p>Both are space members under the existing capability model (<a href="./../../space-authorization-model">space-authorization-model.md</a>). The UI distinguishes them; the auth layer does not.</p><p>Users address bots inline with <code>@bot:&lt;alias&gt;</code>. Bot mentions render as a pill with a distinct icon and surface tint so the user sees at a glance that the mention will dispatch a command to a bot runtime, not generate an LLM completion. When the composer text begins with <code>@bot:</code>, the send button flips its label to <code>Dispatch</code> and the composer left-edge picks up the bot-mention tint.</p><h3 id="_5-backend-switcher-in-the-composer-footer" tabindex="-1">5. Backend switcher in the composer footer <a class="header-anchor" href="#_5-backend-switcher-in-the-composer-footer" aria-label="Permalink to &quot;5. Backend switcher in the composer footer&quot;">​</a></h3><p>The ACP backend picker sits in the <strong>composer footer</strong> as a chip — <code>&lt;provider-mark&gt; &lt;name&gt; ↕</code> — not in the chat header. Vertical chrome stays free; the control lives where the user&#39;s eye is when picking. The dropdown also surfaces &quot;Add backend…&quot; which deep-links to the Assistant settings tab.</p><h3 id="_6-inline-failures-no-toast-only-feedback-for-primary-actions" tabindex="-1">6. Inline failures, no toast-only feedback for primary actions <a class="header-anchor" href="#_6-inline-failures-no-toast-only-feedback-for-primary-actions" aria-label="Permalink to &quot;6. Inline failures, no toast-only feedback for primary actions&quot;">​</a></h3><p>Any primary action (saving settings, issuing a capability, dispatching to a bot, attaching a file) renders failures in the same surface the success would have rendered in. Toast-only errors are banned for these paths. Toasts remain valid for cross-cutting transient notifications (e.g. exercise completion, see §10).</p><h3 id="_7-density-is-a-token-system-not-a-feeling" tabindex="-1">7. Density is a token system, not a feeling <a class="header-anchor" href="#_7-density-is-a-token-system-not-a-feeling" aria-label="Permalink to &quot;7. Density is a token system, not a feeling&quot;">​</a></h3><ul><li><strong>Font sizes:</strong> 14px body, 13px UI-sm, 11px UI-xs.</li><li><strong>Line-height:</strong> <strong>1.5</strong> for body, 1.2 for UI chrome. The original PRD specced 1.45 — the refs pass bumped it after every dense product surveyed (Linear, Mercury, Resend) ran at ~1.5 at 14px.</li><li><strong>Row heights:</strong> 32 / 40 / 52px tiers for dense / cozy / oversized lists.</li><li><strong>Borders vs shadows.</strong> 1px borders + a background step on every elevated surface. <strong>One</strong> shadow token, reserved for modal + popup window. Everywhere else borders carry the elevation.</li><li><strong>Border radius.</strong> <code>rounded-md</code> (6px) max for surfaces, <code>rounded-sm</code> for chips.</li></ul><p>A <code>DensityProvider</code> exists in <code>@soma/ui</code> for future cozy / oversized variants; v0 ships dense only.</p><h3 id="_8-empty-is-a-single-primitive-with-three-variants" tabindex="-1">8. <code>Empty</code> is a single primitive with three variants <a class="header-anchor" href="#_8-empty-is-a-single-primitive-with-three-variants" aria-label="Permalink to &quot;8. `Empty` is a single primitive with three variants&quot;">​</a></h3><p>All empty states use the <code>Empty</code> component:</p><ul><li><strong>Full</strong> — icon + headline + optional one-line subtext + optional single CTA.</li><li><strong>Compact</strong> — dashed-border single line, no icon, no CTA. For narrow panels (chat, attachments, sub-pages).</li><li><strong>Filter</strong> — same shape as the active variant, but the CTA becomes <code>Clear filter ×</code> (secondary slot).</li></ul><p>The empty <em>document</em> is <strong>not</strong> an <code>Empty</code> use — it&#39;s an editor placeholder.</p><h3 id="_9-denserow-is-the-single-list-row-primitive" tabindex="-1">9. <code>DenseRow</code> is the single list-row primitive <a class="header-anchor" href="#_9-denserow-is-the-single-list-row-primitive" aria-label="Permalink to &quot;9. `DenseRow` is the single list-row primitive&quot;">​</a></h3><p>Members, bots, attachments, recent docs, and any future list of objects share one row primitive: <code>leading · primary (+sub) · status pill · meta · always-visible ⋯</code>. Overflow menus are <strong>never</strong> hover-only — actions are always visible.</p><h3 id="_10-multi-window-for-focus-tasks-via-a-reusable-popupshell" tabindex="-1">10. Multi-window for focus tasks via a reusable <code>PopupShell</code> <a class="header-anchor" href="#_10-multi-window-for-focus-tasks-via-a-reusable-popupshell" aria-label="Permalink to &quot;10. Multi-window for focus tasks via a reusable `PopupShell`&quot;">​</a></h3><p>Focus tasks (typing in v0; exams and surveys later) open in their own <code>BrowserWindow</code>, routed by <code>#/popup/&lt;task&gt;/&lt;id&gt;</code>. The popup chrome is a reusable <code>@soma/ui</code> component: 520×360 default, min-width 480px, auto-hide to a 28px drag strip on input focus. Glyph cluster in the drag region, flush-right: <strong>pin</strong> (always-on-top toggle, default off) · <strong>restart</strong> · <strong>return-to-main</strong> (closes popup + focuses main, leaves state resumable) · <strong>close</strong>. The OS window title is the task&#39;s own name, not <code>Soma — Typing</code>, so the popup is identifiable in the dock / window switcher.</p><p>Completion of a focus task closes the popup, refocuses main, and emits a single toast (the one allowed toast pattern in v0): <code>&lt;Task&gt; complete · &lt;metric&gt; · &lt;metric&gt; · View result</code>.</p><h3 id="_11-editor-surfaces-slash-menu-selection-bubble-block-menus" tabindex="-1">11. Editor surfaces: slash menu, selection bubble, block menus <a class="header-anchor" href="#_11-editor-surfaces-slash-menu-selection-bubble-block-menus" aria-label="Permalink to &quot;11. Editor surfaces: slash menu, selection bubble, block menus&quot;">​</a></h3><ul><li><strong>SlashMenu.</strong> Single-column popover anchored at the caret. Rows = monochrome icon + label + right-aligned shortcut hint. Sections in fixed order: Text · List · Embed · Action · Advanced. Substring filter across labels + aliases. <strong>No AI tile</strong> — AI lives in the right-area chat panel; a slash AI block would duplicate intent across surfaces.</li><li><strong>SelectionBubble.</strong> Single dark pill above selection. Order: <code>&lt;block-style ▾&gt;</code> · B · i · U · S · <code>&lt;/&gt;</code> · link · highlight · comment · <code>⋯</code>. Dividers between block / inline / action clusters. The link icon swaps the row into a single-input link mode in place.</li><li><strong>Block hover affordances.</strong> Left gutter (~24px) holds a <code>⋮⋮</code> drag handle and a <code>+</code> insert-below button, hover-only. Right-click anywhere in the row opens the per-block menu.</li></ul><p>Inline AI is a third editor surface alongside SlashMenu and SelectionBubble — see §13. SlashMenu still has no AI tile (the lock above holds); instead, the SlashMenu&#39;s leading input row doubles as the AI prompt entry when the typed text does not match a block name. SelectionBubble grows a trailing &quot;Ask AI&quot; chip that opens the SelectionAIBar; the bubble itself remains a formatting surface. Block menus (right-click) gain an <code>AI ▸</code> cluster fed by the per-node-type AI registry.</p><h3 id="_12-document-tree-lives-in-a-popover-not-a-third-pane" tabindex="-1">12. Document tree lives in a popover, not a third pane <a class="header-anchor" href="#_12-document-tree-lives-in-a-popover-not-a-third-pane" aria-label="Permalink to &quot;12. Document tree lives in a popover, not a third pane&quot;">​</a></h3><p>The page tree is <strong>not</strong> a third docked pane. It opens as a popover anchored under the last breadcrumb segment in the document column header, with sections Search / Recent / Starred / All pages and a footer chip-strip teaching keyboard shortcuts. Scope defaults to the current space; Tab widens to all spaces.</p><p>The tree itself is built on <a href="https://www.npmjs.com/package/react-complex-tree" target="_blank" rel="noreferrer"><code>react-complex-tree</code></a>, which gives us keyboard nav, drag-and-drop reordering, and virtualization for large trees without reimplementing them. Any other tree UI in the renderer (e.g. the legacy page-tree in <code>desktop/soma</code>) migrates to the same library so we don&#39;t carry two tree implementations.</p><p>A separate ⌘K <strong>CommandPalette</strong> covers cross-cutting navigation: Recent docs (any space) → Spaces → Documents → Commands.</p><h3 id="_13-inline-ai-as-a-content-transformation-surface" tabindex="-1">13. Inline AI as a content-transformation surface <a class="header-anchor" href="#_13-inline-ai-as-a-content-transformation-surface" aria-label="Permalink to &quot;13. Inline AI as a content-transformation surface&quot;">​</a></h3><p>Inline AI is a transformation surface bound to a <em>selection</em>, <em>caret position</em>, or <em>node</em> — distinct from the conversational chat panel (§4 / PRD §4.5) and from the block-inserting SlashMenu (§11). It is invoked by <code>⌘J</code>, by the trailing chip on the SelectionBubble, by the SlashMenu input row when not matching a block name, or by the <code>AI ▸</code> cluster in a node&#39;s right-click menu.</p><p>Results stream into the document at the invocation site. A single accept bar — <code>Accept</code> · <code>Try again</code> · <code>Refine…</code> · <code>Discard</code> — closes the interaction. While streaming, the affected region is non-editable and renders in the accent color with a dashed accent underline; a <code>Thinking…</code> pill (same component as the chat panel) covers the pre-first-token window.</p><p>Every inline AI invocation appends a collapsed turn to the chat panel as audit log, and the inline accept bar exposes <code>Open in chat</code> for escalation into a full conversation when a one-shot rewrite needs to become a discussion. This keeps the chat panel as the single conversation/audit surface (§4 / PRD §4.5) without forcing a panel context switch for one-shot edits.</p><p>No diff view in v0 (prose-first; diffs become opt-in later for code-block nodes). No per-paragraph hover AI button. No separate <code>/ai</code> slash command. One surface, multiple invocation paths, one accept bar.</p><p>Detailed visual specification and the reference pass that produced this decision live in <a href="./../prd/ui-revamp-v0-refs-editor-ai">prd/ui-revamp-v0-refs-editor-ai.md</a>.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>Positive:</p><ul><li>One UI system kills the second-tree maintenance tax inside <code>practice/</code>.</li><li>Treating the right area as a panel stack (vs &quot;the chat panel&quot;) matches actual usage and avoids the trap of cramming history/agenda/sub-pages into chat.</li><li>ACP unifies the LLM integration story behind a single contract; switching providers becomes a config change, not a refactor.</li><li>The LLM-vs-bot split makes the <code>@bot:</code> mention semantically clear and lets the auth model stay simple (both are members; UI carries the distinction).</li><li>Density tokens stop being negotiable per screen. New screens inherit the system.</li><li>The <code>DenseRow</code> and <code>Empty</code> primitives prevent the visual drift that produced &quot;buttons everywhere&quot; the first time around.</li><li>Multi-window via a reusable <code>PopupShell</code> makes future focus tasks (exams, surveys) a route, not a project.</li></ul><p>Negative / follow-ups:</p><ul><li>The &quot;no catalog&quot; decision for bots means a less discoverable v0; bot directories and friend-of-friend discovery are explicitly deferred.</li><li>ACP plumbing inside <code>soma-agentd</code> is a new surface; the v0 implementation must verify that the napi handle exposes enough state for the composer-footer switcher to stay live.</li><li>The <code>PanelContainer</code> user-driven horizontal split has no clean prior art in our refs (closest is VS Code editor groups); we expect to iterate the gesture/keyboard surface post-v0.</li><li>Settings auto-save mandates per-field validators that can run on blur without round-trips; the embedded daemon makes this cheap, but it has to be done deliberately.</li><li>Bot status streaming requires the daemon to expose a per-space subscription channel; the PRD already calls this out as a backend item to verify.</li></ul><h2 id="implementation-status" tabindex="-1">Implementation status <a class="header-anchor" href="#implementation-status" aria-label="Permalink to &quot;Implementation status&quot;">​</a></h2><ul><li>Decision recorded; PRD revised against the refs pass on 2026-05-18.</li><li>ADR governs the next phase: a <code>@soma/ui</code> component scaffolding plan (one Storybook story per new component before any consumer wires it in <code>desktop/soma</code>).</li><li>First implementation cut targets §4.4 + §4.2 (space settings + bots tab) because &quot;add a bot&quot; is the v0 product priority.</li></ul><h2 id="related-material" tabindex="-1">Related material <a class="header-anchor" href="#related-material" aria-label="Permalink to &quot;Related material&quot;">​</a></h2><ul><li>PRD: <a href="./../prd/ui-revamp-v0">prd/ui-revamp-v0.md</a></li><li>Refs (overview): <a href="./../prd/ui-revamp-v0-refs">prd/ui-revamp-v0-refs.md</a></li><li>Refs (space lifecycle, §4.1 / §4.2 / §4.8): <a href="./../prd/ui-revamp-v0-refs-space-lifecycle">prd/ui-revamp-v0-refs-space-lifecycle.md</a></li><li>Refs (assistant + bots, §4.3 / §4.4 status / §4.6 / streaming): <a href="./../prd/ui-revamp-v0-refs-assistant-bots">prd/ui-revamp-v0-refs-assistant-bots.md</a></li><li>Refs (editor, §6 SlashMenu / SelectionBubble / block menus): <a href="./../prd/ui-revamp-v0-refs-editor">prd/ui-revamp-v0-refs-editor.md</a></li><li>Refs (inline editor AI, §13): <a href="./../prd/ui-revamp-v0-refs-editor-ai">prd/ui-revamp-v0-refs-editor-ai.md</a></li><li>Refs (files + density tokens + DenseRow + Empty): <a href="./../prd/ui-revamp-v0-refs-files-density">prd/ui-revamp-v0-refs-files-density.md</a></li><li>Refs (popup window, §4.7 chrome): <a href="./../prd/ui-revamp-v0-refs-popup-window">prd/ui-revamp-v0-refs-popup-window.md</a></li><li>Capability model context: <a href="./../../space-authorization-model">space-authorization-model.md</a></li><li>Backend collapse context: ADR-0001 (Superseded)</li></ul>',59)])])}const m=t(i,[["render",n]]);export{u as __pageData,m as default};
